      analysis_version: "1.0",

      alert_id: "ALERT-0001",

      summary:
        "User authenticated from geographically distant locations within an unusual time window.",

      observed_evidence: [
        {
          field: "users",
          value: [
            "john.doe@example.com"
          ]
        },
        {
          field: "hosts",
          value: [
            "WIN11-LAPTOP-01"
          ]
        },
        {
          field: "source_ips",
          value: [
            "185.220.101.20"
          ]
        },
        {
          field: "destination_ips",
          value: [
            "20.190.128.25"
          ]
        },
        {
          field: "authentication_method",
          value: "MFA"
        },
        {
          field: "geographic_observations.reported_locations",
          value: [
            "Spain",
            "Netherlands"
          ]
        }
      ],

      hypotheses: [],

      risk_assessment: {
        level: "unknown",
        reasoning: [
          "Geographic locations reported are not explicitly linked to IP addresses or user authentication events."
        ]
      },

      missing_evidence: [
        "Explicit mapping of reported geographic locations to IP addresses or user authentication events.",
        "Historical sign-in data to assess unusual travel patterns.",
        "Endpoint activity details to confirm user behavior."
      ],

      preliminary_verdict: "inconclusive",

      confidence: 0,

      recommended_investigations: [
        "Verify if the reported geographic locations are explicitly associated with the source or destination IP addresses.",
        "Collect historical sign-in data to analyze authentication patterns.",
        "Gather endpoint activity details to confirm user behavior."
      ]
    }
  }
];

const analysis = $json;

// --------------------------------------------------
// 1. Allowed investigation tools
// --------------------------------------------------
//
// Tool capabilities are deliberately narrow.
//
// The planner may only request evidence that a tool
// is explicitly documented as being able to collect.
// --------------------------------------------------

const allowedTools = {
  get_signins: {
    description:
      "Retrieve authentication and sign-in events for a specific user.",
    capabilities: [
      "Retrieve historical user sign-ins",
      "Retrieve authentication timestamps",
      "Retrieve IP addresses observed in authentication events",
      "Retrieve authentication results and available authentication context"
    ],
    limitations: [
      "Does not provide endpoint telemetry",
      "Does not provide email activity",
      "Does not provide authoritative threat intelligence"
    ],
    required_parameters: [
      "user"
    ]
  },

  get_ip_reputation: {
    description:
      "Retrieve threat intelligence and reputation information for a specific IP address.",
    capabilities: [
      "Retrieve known malicious or suspicious reputation",
      "Retrieve threat intelligence information when available"
    ],
    limitations: [
      "Must not be used as an authoritative IP-to-country mapping tool",
      "Must not infer where a user authenticated from",
      "Must not establish a relationship between an IP address and a geographic observation unless the tool explicitly returns such evidence"
    ],
    required_parameters: [
      "ip"
    ]
  },

  get_endpoint_activity: {
    description:
      "Retrieve security telemetry and activity associated with a specific endpoint or host.",
    capabilities: [
      "Retrieve endpoint security activity",
      "Retrieve relevant endpoint events",
      "Retrieve available process or detection activity"
    ],
    limitations: [
      "Does not establish identity sign-in history",
      "Does not provide email activity",
      "Does not provide authoritative IP geolocation"
    ],
    required_parameters: [
      "host"
    ]
  },

  get_user_activity: {
    description:
      "Retrieve relevant user activity outside authentication events.",
    capabilities: [
      "Retrieve available user activity",
      "Retrieve relevant actions associated with a user identity"
    ],
    limitations: [
      "Does not replace dedicated authentication telemetry",
      "Does not provide endpoint telemetry unless explicitly returned by the underlying source"
    ],
    required_parameters: [
      "user"
    ]
  },

  get_mail_activity: {
    description:
      "Retrieve email activity associated with a specific user.",
    capabilities: [
      "Retrieve relevant sent or received email activity",
      "Retrieve available mail security context"
    ],
    limitations: [
      "Does not provide endpoint telemetry",
      "Does not establish IP geolocation"
    ],
    required_parameters: [
      "user"
    ]
  }
};

// --------------------------------------------------
// 2. Expected output structure
// --------------------------------------------------

const expectedOutput = {
  plan_version: "1.0",

  alert_id:
    analysis.alert_id || "",

  objective:
    "Describe the investigation objective.",

  investigation_steps: [
    {
      step_id: "step-1",

      priority: "high",

      purpose:
        "Explain why this investigation step is required.",

      tool:
        "get_signins",

      parameters: {
        user:
          "user@example.com"
      },

      evidence_target:
        "Describe only evidence that the selected tool is explicitly capable of collecting."
    }
  ]
};

// --------------------------------------------------
// 3. System prompt
// --------------------------------------------------

const systemPrompt =
  "You are an investigation planner for a cybersecurity SOC. " +

  "Your role is to create an executable evidence-collection plan, not to perform the investigation. " +

  "Use only the evidence and investigation requirements present in the validated analysis. " +

  "Do not invent users, hosts, IP addresses, evidence, relationships, tool capabilities, or tools. " +

  "A valid tool name does not imply that the tool can answer every investigation question. " +

  "Every investigation step must request evidence that the selected tool is explicitly documented as being capable of collecting. " +

  "Respect all tool limitations. " +

  "If no available tool can collect a required piece of evidence, omit that requirement from the executable investigation_steps. " +

  "Do not perform containment or remediation actions. " +

  "Return only valid JSON. " +

  "Do not use Markdown, code fences, comments, or explanatory text outside the JSON object.";

// --------------------------------------------------
// 4. User prompt
// --------------------------------------------------

const userPrompt =
  "Create a structured SOC investigation plan from the validated initial analysis. " +

  "AVAILABLE TOOLS AND THEIR EXACT CAPABILITIES: " +
  JSON.stringify(allowedTools) +
  ". " +

  "Return exactly one JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY RULES: " +

  "1. plan_version must be exactly '1.0'. " +

  "2. alert_id must exactly match the input analysis alert_id. " +

  "3. objective must be a concise non-empty description of what the investigation needs to determine. " +

  "4. investigation_steps must contain only steps justified by missing_evidence, recommended_investigations, observed_evidence, or hypotheses from the validated analysis. " +

  "5. tool must be one of the provided available tool names. Never invent a tool. " +

  "6. parameters may contain only entity values explicitly present in observed_evidence. Never invent users, IP addresses, hosts, domains, email addresses, or other entities. " +

  "7. Each selected tool may only be used for capabilities explicitly listed in its capabilities field. " +

  "8. Respect every limitation declared for the selected tool. " +

  "9. Do not use get_ip_reputation to establish an authoritative mapping between an IP address and Spain, Netherlands, or any other geographic observation. " +

  "10. Do not use any available tool to claim that a user authenticated from Spain or Netherlands unless collected evidence explicitly establishes that relationship. " +

  "11. If the analysis requires evidence that no available tool can collect, do not invent a substitute tool or misuse another tool. Omit that requirement from investigation_steps. " +

  "12. It is valid for an executable investigation plan to cover only part of the missing evidence when the remaining evidence cannot currently be collected by the available tools. " +

  "13. priority must be one of: high, medium, low. " +

  "14. step_id values must start at step-1 and increase sequentially without gaps. " +

  "15. purpose must explain why the selected tool should be executed. " +

  "16. evidence_target must describe evidence the selected tool can actually return. It must not describe a desired conclusion or predicted result. " +

  "17. get_ip_reputation may be used to determine whether an observed IP has suspicious or malicious reputation, but not to prove its geographic relationship to an authentication event. " +

  "18. get_signins may be used to retrieve historical authentication activity for an explicitly observed user. " +

  "19. get_endpoint_activity may be used to retrieve endpoint activity for an explicitly observed host. " +

  "20. Do not include remediation, containment, blocking, account disablement, password reset, session revocation, or destructive actions. " +

  "Validated analysis: " +
  JSON.stringify(analysis);

// --------------------------------------------------
// 5. Ollama request
// --------------------------------------------------

return [
  {
    json: {
      model: "qwen3:8b",

      messages: [
        {
          role: "system",
          content: systemPrompt
        },
        {
          role: "user",
          content: userPrompt
        }
      ],

      stream: false,

      think: false,

      keep_alive: "5m",

      format: "json"
    }
  }
];

// ==================================================
// Investigation Plan Validator
//
// Purpose:
// Validate an LLM-generated investigation plan
// without stopping the workflow.
//
// Output:
// {
//   valid: boolean,
//   errors: [],
//   plan: {},
//   validation_metadata: {}
// }
//
// LLM output is always treated as untrusted input.
// ==================================================


// --------------------------------------------------
// 1. Extract Ollama response
// --------------------------------------------------

const response = $json;

const content = response?.message?.content;


// --------------------------------------------------
// 2. Prepare validation result
// --------------------------------------------------

const errors = [];

let plan = null;


// --------------------------------------------------
// 3. Validate message.content
// --------------------------------------------------

if (
  !content ||
  typeof content !== "string"
) {
  errors.push(
    "message.content is missing or empty"
  );
}


// --------------------------------------------------
// 4. Parse LLM JSON
// --------------------------------------------------

if (errors.length === 0) {
  try {
    plan = JSON.parse(content);
  } catch (error) {
    errors.push(
      `response is not valid JSON: ${error.message}`
    );
  }
}


// --------------------------------------------------
// 5. Retrieve validated canonical analysis
// --------------------------------------------------

const analysis =
  $("Canonical Analysis Input").first().json;


// --------------------------------------------------
// 6. Helper functions
// --------------------------------------------------

function requireString(field, value) {
  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function containsAny(text, patterns) {
  if (typeof text !== "string") {
    return false;
  }

  const normalized =
    text.toLowerCase();

  return patterns.some(
    pattern =>
      normalized.includes(
        pattern.toLowerCase()
      )
  );
}


// --------------------------------------------------
// 7. Extract allowed entities
// --------------------------------------------------

const allowedUsers = new Set();
const allowedHosts = new Set();
const allowedIps = new Set();

for (
  const evidence
  of analysis.observed_evidence || []
) {

  if (
    !evidence ||
    typeof evidence !== "object"
  ) {
    continue;
  }

  const field =
    evidence.field;

  const value =
    evidence.value;

  const values =
    Array.isArray(value)
      ? value
      : [value];

  for (const item of values) {

    if (
      item === null ||
      item === undefined
    ) {
      continue;
    }

    const normalized =
      String(item).trim();

    if (!normalized) {
      continue;
    }

    if (field === "users") {
      allowedUsers.add(normalized);
    }

    if (field === "hosts") {
      allowedHosts.add(normalized);
    }

    if (
      field === "source_ips" ||
      field === "destination_ips" ||
      field === "related_ips"
    ) {
      allowedIps.add(normalized);
    }
  }
}


// --------------------------------------------------
// 8. Tool policies
// --------------------------------------------------

const toolPolicies = {

  get_signins: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint activity",
      "email activity",
      "malicious reputation",
      "ip reputation"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "email activity",
      "ip reputation"
    ]
  },


  get_ip_reputation: {
    requiredParameters: [
      "ip"
    ],

    allowedParameters: [
      "ip"
    ],

    entityValidation: {
      parameter: "ip",
      allowedValues: allowedIps
    },

    forbiddenPurposePatterns: [
      "geographic",
      "geolocation",
      "country",
      "location",
      "associated with the reported geographic",
      "linked to the reported geographic",
      "authenticated from"
    ],

    forbiddenEvidencePatterns: [
      "geographic mapping",
      "geolocation mapping",
      "country mapping",
      "authenticated from",
      "user location"
    ]
  },


  get_endpoint_activity: {
    requiredParameters: [
      "host"
    ],

    allowedParameters: [
      "host"
    ],

    entityValidation: {
      parameter: "host",
      allowedValues: allowedHosts
    },

    forbiddenPurposePatterns: [
      "historical sign-in",
      "email activity",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "historical sign-in",
      "ip reputation",
      "email activity"
    ]
  },


  get_user_activity: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint telemetry",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "ip reputation"
    ]
  },


  get_mail_activity: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint telemetry",
      "historical sign-in",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "historical sign-in",
      "ip reputation"
    ]
  }
};


// --------------------------------------------------
// 9. Validate parsed plan
// --------------------------------------------------

if (
  plan !== null &&
  typeof plan === "object" &&
  !Array.isArray(plan)
) {

  // ----------------------------------------------
  // Plan version
  // ----------------------------------------------

  if (plan.plan_version !== "1.0") {
    errors.push(
      "plan_version must be '1.0'"
    );
  }


  // ----------------------------------------------
  // Alert ID
  // ----------------------------------------------

  requireString(
    "alert_id",
    plan.alert_id
  );


  if (
    typeof plan.alert_id === "string" &&
    plan.alert_id !== analysis.alert_id
  ) {
    errors.push(
      "alert_id does not match the validated analysis"
    );
  }


  // ----------------------------------------------
  // Objective
  // ----------------------------------------------

  requireString(
    "objective",
    plan.objective
  );


  // ----------------------------------------------
  // Investigation steps
  // ----------------------------------------------

  if (
    !Array.isArray(
      plan.investigation_steps
    )
  ) {
    errors.push(
      "investigation_steps must be an array"
    );
  } else {

    if (
      plan.investigation_steps.length === 0
    ) {
      errors.push(
        "investigation_steps must contain at least one step"
      );
    }


    const validPriorities = [
      "high",
      "medium",
      "low"
    ];


    plan.investigation_steps.forEach(
      (step, index) => {

        const prefix =
          `investigation_steps[${index}]`;


        // ----------------------------------------
        // Step object
        // ----------------------------------------

        if (
          typeof step !== "object" ||
          step === null ||
          Array.isArray(step)
        ) {
          errors.push(
            `${prefix} must be an object`
          );

          return;
        }


        // ----------------------------------------
        // Sequential step ID
        // ----------------------------------------

        const expectedStepId =
          `step-${index + 1}`;

        if (
          step.step_id !== expectedStepId
        ) {
          errors.push(
            `${prefix}.step_id must be '${expectedStepId}'`
          );
        }


        // ----------------------------------------
        // Priority
        // ----------------------------------------

        if (
          !validPriorities.includes(
            step.priority
          )
        ) {
          errors.push(
            `${prefix}.priority contains an invalid value`
          );
        }


        // ----------------------------------------
        // Purpose
        // ----------------------------------------

        requireString(
          `${prefix}.purpose`,
          step.purpose
        );


        // ----------------------------------------
        // Evidence target
        // ----------------------------------------

        requireString(
          `${prefix}.evidence_target`,
          step.evidence_target
        );


        // ----------------------------------------
        // Tool allowlist
        // ----------------------------------------

        if (
          typeof step.tool !== "string" ||
          !Object.prototype.hasOwnProperty.call(
            toolPolicies,
            step.tool
          )
        ) {
          errors.push(
            `${prefix}.tool '${step.tool}' is not allowed`
          );

          return;
        }


        const policy =
          toolPolicies[step.tool];


        // ----------------------------------------
        // Parameters
        // ----------------------------------------

        if (
          typeof step.parameters !== "object" ||
          step.parameters === null ||
          Array.isArray(step.parameters)
        ) {
          errors.push(
            `${prefix}.parameters must be an object`
          );

          return;
        }


        // ----------------------------------------
        // Required parameters
        // ----------------------------------------

        for (
          const requiredParameter
          of policy.requiredParameters
        ) {

          if (
            !Object.prototype.hasOwnProperty.call(
              step.parameters,
              requiredParameter
            )
          ) {
            errors.push(
              `${prefix}.parameters.${requiredParameter} is required for ${step.tool}`
            );
          }
        }


        // ----------------------------------------
        // Unexpected parameters
        // ----------------------------------------

        for (
          const parameterName
          of Object.keys(
            step.parameters
          )
        ) {

          if (
            !policy.allowedParameters.includes(
              parameterName
            )
          ) {
            errors.push(
              `${prefix}.parameters.${parameterName} is not allowed for ${step.tool}`
            );
          }
        }


        // ----------------------------------------
        // Entity validation
        // ----------------------------------------

        const entityRule =
          policy.entityValidation;

        if (entityRule) {

          const value =
            step.parameters[
              entityRule.parameter
            ];

          if (
            typeof value !== "string" ||
            value.trim() === ""
          ) {
            errors.push(
              `${prefix}.parameters.${entityRule.parameter} must be a non-empty string`
            );
          } else if (
            !entityRule.allowedValues.has(
              value
            )
          ) {
            errors.push(
              `${prefix}.parameters.${entityRule.parameter} contains an entity not present in observed evidence: ${value}`
            );
          }
        }


        // ----------------------------------------
        // Semantic capability validation
        // ----------------------------------------

        if (
          policy.forbiddenPurposePatterns &&
          containsAny(
            step.purpose,
            policy.forbiddenPurposePatterns
          )
        ) {
          errors.push(
            `${prefix}: tool '${step.tool}' is being used for a purpose outside its allowed capabilities`
          );
        }


        if (
          policy.forbiddenEvidencePatterns &&
          containsAny(
            step.evidence_target,
            policy.forbiddenEvidencePatterns
          )
        ) {
          errors.push(
            `${prefix}: evidence_target requests evidence outside the capabilities of '${step.tool}'`
          );
        }
      }
    );
  }

} else if (plan !== null) {

  errors.push(
    "investigation plan must be a JSON object"
  );
}


// --------------------------------------------------
// 10. Final validation result
// --------------------------------------------------

const valid =
  errors.length === 0;


// --------------------------------------------------
// 11. Controlled output
// --------------------------------------------------

return [
  {
    json: {
      valid,

      errors,

      plan,

      validation_metadata: {
        validator:
          "investigation_plan_validator",

        validator_version:
          "1.0",

        validated_at:
          new Date().toISOString(),

        error_count:
          errors.length
      }
    }
  }
];

const validationResult = $json;

// --------------------------------------------------
// Validate expected state
// --------------------------------------------------

if (validationResult.valid !== true) {
  throw new Error(
    "Valid Investigation Plan received an invalid validation result"
  );
}

if (
  !validationResult.plan ||
  typeof validationResult.plan !== "object"
) {
  throw new Error(
    "Valid Investigation Plan received no canonical plan"
  );
}


// --------------------------------------------------
// Return only the canonical investigation plan
// --------------------------------------------------

return [
  {
    json: validationResult.plan
  }
];

const validationResult = $json;


// --------------------------------------------------
// 1. Validate repair input
// --------------------------------------------------

if (validationResult.valid !== false) {
  throw new Error(
    "Plan Repair Request Builder received a valid plan"
  );
}


if (
  !validationResult.plan ||
  typeof validationResult.plan !== "object"
) {
  throw new Error(
    "Plan Repair Request Builder received no plan to repair"
  );
}


if (
  !Array.isArray(validationResult.errors) ||
  validationResult.errors.length === 0
) {
  throw new Error(
    "Plan Repair Request Builder received no validation errors"
  );
}


// --------------------------------------------------
// 2. Retrieve canonical analysis
// --------------------------------------------------

const analysis =
  $("Canonical Analysis Input").first().json;


// --------------------------------------------------
// 3. Allowed tools
// --------------------------------------------------

const allowedTools = {

  get_signins: {
    capabilities: [
      "Retrieve historical user sign-ins",
      "Retrieve authentication timestamps",
      "Retrieve IP addresses observed in authentication events",
      "Retrieve authentication results and available authentication context"
    ],

    limitations: [
      "Does not provide endpoint telemetry",
      "Does not provide authoritative threat intelligence"
    ],

    required_parameters: [
      "user"
    ]
  },


  get_ip_reputation: {
    capabilities: [
      "Retrieve malicious or suspicious IP reputation",
      "Retrieve threat intelligence information when available"
    ],

    limitations: [
      "Must not be used as an authoritative IP-to-country mapping tool",
      "Must not establish where a user authenticated from",
      "Must not prove relationships between geographic observations and authentication events"
    ],

    required_parameters: [
      "ip"
    ]
  },


  get_endpoint_activity: {
    capabilities: [
      "Retrieve endpoint security activity",
      "Retrieve endpoint events",
      "Retrieve available process or detection activity"
    ],

    limitations: [
      "Does not establish historical identity sign-ins",
      "Does not provide authoritative IP geolocation"
    ],

    required_parameters: [
      "host"
    ]
  },


  get_user_activity: {
    capabilities: [
      "Retrieve relevant activity associated with a user"
    ],

    limitations: [
      "Does not replace dedicated authentication telemetry",
      "Does not provide endpoint telemetry unless explicitly returned"
    ],

    required_parameters: [
      "user"
    ]
  },


  get_mail_activity: {
    capabilities: [
      "Retrieve relevant sent or received email activity",
      "Retrieve available mail security context"
    ],

    limitations: [
      "Does not provide endpoint telemetry",
      "Does not establish IP geolocation"
    ],

    required_parameters: [
      "user"
    ]
  }
};


// --------------------------------------------------
// 4. Expected output
// --------------------------------------------------

const expectedOutput = {
  plan_version: "1.0",

  alert_id:
    analysis.alert_id,

  objective:
    "Correct investigation objective.",

  investigation_steps: [
    {
      step_id:
        "step-1",

      priority:
        "high",

      purpose:
        "Purpose supported by the selected tool capability.",

      tool:
        "get_signins",

      parameters: {
        user:
          "user@example.com"
      },

      evidence_target:
        "Evidence explicitly supported by the selected tool."
    }
  ]
};


// --------------------------------------------------
// 5. System prompt
// --------------------------------------------------

const systemPrompt =
  "You are repairing an invalid cybersecurity investigation plan. " +

  "The previous plan was rejected by deterministic security validation. " +

  "You must correct the plan according to the validation errors. " +

  "Do not defend the previous plan. " +

  "Do not ignore validation errors. " +

  "Do not invent tools, entities, evidence, relationships, or capabilities. " +

  "Every investigation step must use a tool only for its explicitly documented capabilities. " +

  "If no available tool can collect a required piece of evidence, omit that executable step. " +

  "Return only valid JSON. " +

  "Do not use Markdown, code fences, comments, or explanatory text outside the JSON object.";


// --------------------------------------------------
// 6. Repair prompt
// --------------------------------------------------

const userPrompt =
  "Repair the rejected SOC investigation plan. " +

  "VALIDATED ANALYSIS: " +
  JSON.stringify(analysis) +
  ". " +

  "REJECTED PLAN: " +
  JSON.stringify(validationResult.plan) +
  ". " +

  "VALIDATION ERRORS: " +
  JSON.stringify(validationResult.errors) +
  ". " +

  "AVAILABLE TOOL CAPABILITIES: " +
  JSON.stringify(allowedTools) +
  ". " +

  "Return exactly one corrected JSON object matching this structure: " +
  JSON.stringify(expectedOutput) +
  ". " +

  "MANDATORY REPAIR RULES: " +

  "1. Correct every validation error. " +

  "2. plan_version must be '1.0'. " +

  "3. alert_id must remain exactly equal to the validated analysis alert_id. " +

  "4. Keep only executable investigation steps supported by available tools. " +

  "5. Do not use get_ip_reputation to determine whether Spain, Netherlands, or another geographic observation corresponds to an IP address. " +

  "6. get_ip_reputation may only request threat intelligence or reputation evidence for an observed IP. " +

  "7. get_signins may retrieve historical authentication activity for an observed user. " +

  "8. get_endpoint_activity may retrieve endpoint evidence for an observed host. " +

  "9. Never invent parameter values. " +

  "10. If a required investigation cannot be performed with the available tools, omit that step. " +

  "11. Renumber step_id sequentially starting from step-1 after removing or changing invalid steps. " +

  "12. Do not perform remediation or containment actions.";


// --------------------------------------------------
// 7. Ollama request
// --------------------------------------------------

return [
  {
    json: {
      model:
        "qwen3:8b",

      messages: [
        {
          role:
            "system",

          content:
            systemPrompt
        },
        {
          role:
            "user",

          content:
            userPrompt
        }
      ],

      stream:
        false,

      think:
        false,

      keep_alive:
        "5m",

      format:
        "json"
    }
  }
];

// ==================================================
// Investigation Plan Validator
//
// Purpose:
// Validate an LLM-generated investigation plan
// without stopping the workflow.
//
// Output:
// {
//   valid: boolean,
//   errors: [],
//   plan: {},
//   validation_metadata: {}
// }
//
// LLM output is always treated as untrusted input.
// ==================================================


// --------------------------------------------------
// 1. Extract Ollama response
// --------------------------------------------------

const response = $json;

const content = response?.message?.content;


// --------------------------------------------------
// 2. Prepare validation result
// --------------------------------------------------

const errors = [];

let plan = null;


// --------------------------------------------------
// 3. Validate message.content
// --------------------------------------------------

if (
  !content ||
  typeof content !== "string"
) {
  errors.push(
    "message.content is missing or empty"
  );
}


// --------------------------------------------------
// 4. Parse LLM JSON
// --------------------------------------------------

if (errors.length === 0) {
  try {
    plan = JSON.parse(content);
  } catch (error) {
    errors.push(
      `response is not valid JSON: ${error.message}`
    );
  }
}


// --------------------------------------------------
// 5. Retrieve validated canonical analysis
// --------------------------------------------------

const analysis =
  $("Canonical Analysis Input").first().json;


// --------------------------------------------------
// 6. Helper functions
// --------------------------------------------------

function requireString(field, value) {
  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function containsAny(text, patterns) {
  if (typeof text !== "string") {
    return false;
  }

  const normalized =
    text.toLowerCase();

  return patterns.some(
    pattern =>
      normalized.includes(
        pattern.toLowerCase()
      )
  );
}


// --------------------------------------------------
// 7. Extract allowed entities
// --------------------------------------------------

const allowedUsers = new Set();
const allowedHosts = new Set();
const allowedIps = new Set();

for (
  const evidence
  of analysis.observed_evidence || []
) {

  if (
    !evidence ||
    typeof evidence !== "object"
  ) {
    continue;
  }

  const field =
    evidence.field;

  const value =
    evidence.value;

  const values =
    Array.isArray(value)
      ? value
      : [value];

  for (const item of values) {

    if (
      item === null ||
      item === undefined
    ) {
      continue;
    }

    const normalized =
      String(item).trim();

    if (!normalized) {
      continue;
    }

    if (field === "users") {
      allowedUsers.add(normalized);
    }

    if (field === "hosts") {
      allowedHosts.add(normalized);
    }

    if (
      field === "source_ips" ||
      field === "destination_ips" ||
      field === "related_ips"
    ) {
      allowedIps.add(normalized);
    }
  }
}


// --------------------------------------------------
// 8. Tool policies
// --------------------------------------------------

const toolPolicies = {

  get_signins: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint activity",
      "email activity",
      "malicious reputation",
      "ip reputation"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "email activity",
      "ip reputation"
    ]
  },


  get_ip_reputation: {
    requiredParameters: [
      "ip"
    ],

    allowedParameters: [
      "ip"
    ],

    entityValidation: {
      parameter: "ip",
      allowedValues: allowedIps
    },

    forbiddenPurposePatterns: [
      "geographic",
      "geolocation",
      "country",
      "location",
      "associated with the reported geographic",
      "linked to the reported geographic",
      "authenticated from"
    ],

    forbiddenEvidencePatterns: [
      "geographic mapping",
      "geolocation mapping",
      "country mapping",
      "authenticated from",
      "user location"
    ]
  },


  get_endpoint_activity: {
    requiredParameters: [
      "host"
    ],

    allowedParameters: [
      "host"
    ],

    entityValidation: {
      parameter: "host",
      allowedValues: allowedHosts
    },

    forbiddenPurposePatterns: [
      "historical sign-in",
      "email activity",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "historical sign-in",
      "ip reputation",
      "email activity"
    ]
  },


  get_user_activity: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint telemetry",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "ip reputation"
    ]
  },


  get_mail_activity: {
    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user"
    ],

    entityValidation: {
      parameter: "user",
      allowedValues: allowedUsers
    },

    forbiddenPurposePatterns: [
      "endpoint telemetry",
      "historical sign-in",
      "ip reputation",
      "geographic mapping"
    ],

    forbiddenEvidencePatterns: [
      "endpoint telemetry",
      "historical sign-in",
      "ip reputation"
    ]
  }
};


// --------------------------------------------------
// 9. Validate parsed plan
// --------------------------------------------------

if (
  plan !== null &&
  typeof plan === "object" &&
  !Array.isArray(plan)
) {

  // ----------------------------------------------
  // Plan version
  // ----------------------------------------------

  if (plan.plan_version !== "1.0") {
    errors.push(
      "plan_version must be '1.0'"
    );
  }


  // ----------------------------------------------
  // Alert ID
  // ----------------------------------------------

  requireString(
    "alert_id",
    plan.alert_id
  );


  if (
    typeof plan.alert_id === "string" &&
    plan.alert_id !== analysis.alert_id
  ) {
    errors.push(
      "alert_id does not match the validated analysis"
    );
  }


  // ----------------------------------------------
  // Objective
  // ----------------------------------------------

  requireString(
    "objective",
    plan.objective
  );


  // ----------------------------------------------
  // Investigation steps
  // ----------------------------------------------

  if (
    !Array.isArray(
      plan.investigation_steps
    )
  ) {
    errors.push(
      "investigation_steps must be an array"
    );
  } else {

    if (
      plan.investigation_steps.length === 0
    ) {
      errors.push(
        "investigation_steps must contain at least one step"
      );
    }


    const validPriorities = [
      "high",
      "medium",
      "low"
    ];


    plan.investigation_steps.forEach(
      (step, index) => {

        const prefix =
          `investigation_steps[${index}]`;


        // ----------------------------------------
        // Step object
        // ----------------------------------------

        if (
          typeof step !== "object" ||
          step === null ||
          Array.isArray(step)
        ) {
          errors.push(
            `${prefix} must be an object`
          );

          return;
        }


        // ----------------------------------------
        // Sequential step ID
        // ----------------------------------------

        const expectedStepId =
          `step-${index + 1}`;

        if (
          step.step_id !== expectedStepId
        ) {
          errors.push(
            `${prefix}.step_id must be '${expectedStepId}'`
          );
        }


        // ----------------------------------------
        // Priority
        // ----------------------------------------

        if (
          !validPriorities.includes(
            step.priority
          )
        ) {
          errors.push(
            `${prefix}.priority contains an invalid value`
          );
        }


        // ----------------------------------------
        // Purpose
        // ----------------------------------------

        requireString(
          `${prefix}.purpose`,
          step.purpose
        );


        // ----------------------------------------
        // Evidence target
        // ----------------------------------------

        requireString(
          `${prefix}.evidence_target`,
          step.evidence_target
        );


        // ----------------------------------------
        // Tool allowlist
        // ----------------------------------------

        if (
          typeof step.tool !== "string" ||
          !Object.prototype.hasOwnProperty.call(
            toolPolicies,
            step.tool
          )
        ) {
          errors.push(
            `${prefix}.tool '${step.tool}' is not allowed`
          );

          return;
        }


        const policy =
          toolPolicies[step.tool];


        // ----------------------------------------
        // Parameters
        // ----------------------------------------

        if (
          typeof step.parameters !== "object" ||
          step.parameters === null ||
          Array.isArray(step.parameters)
        ) {
          errors.push(
            `${prefix}.parameters must be an object`
          );

          return;
        }


        // ----------------------------------------
        // Required parameters
        // ----------------------------------------

        for (
          const requiredParameter
          of policy.requiredParameters
        ) {

          if (
            !Object.prototype.hasOwnProperty.call(
              step.parameters,
              requiredParameter
            )
          ) {
            errors.push(
              `${prefix}.parameters.${requiredParameter} is required for ${step.tool}`
            );
          }
        }


        // ----------------------------------------
        // Unexpected parameters
        // ----------------------------------------

        for (
          const parameterName
          of Object.keys(
            step.parameters
          )
        ) {

          if (
            !policy.allowedParameters.includes(
              parameterName
            )
          ) {
            errors.push(
              `${prefix}.parameters.${parameterName} is not allowed for ${step.tool}`
            );
          }
        }


        // ----------------------------------------
        // Entity validation
        // ----------------------------------------

        const entityRule =
          policy.entityValidation;

        if (entityRule) {

          const value =
            step.parameters[
              entityRule.parameter
            ];

          if (
            typeof value !== "string" ||
            value.trim() === ""
          ) {
            errors.push(
              `${prefix}.parameters.${entityRule.parameter} must be a non-empty string`
            );
          } else if (
            !entityRule.allowedValues.has(
              value
            )
          ) {
            errors.push(
              `${prefix}.parameters.${entityRule.parameter} contains an entity not present in observed evidence: ${value}`
            );
          }
        }


        // ----------------------------------------
        // Semantic capability validation
        // ----------------------------------------

        if (
          policy.forbiddenPurposePatterns &&
          containsAny(
            step.purpose,
            policy.forbiddenPurposePatterns
          )
        ) {
          errors.push(
            `${prefix}: tool '${step.tool}' is being used for a purpose outside its allowed capabilities`
          );
        }


        if (
          policy.forbiddenEvidencePatterns &&
          containsAny(
            step.evidence_target,
            policy.forbiddenEvidencePatterns
          )
        ) {
          errors.push(
            `${prefix}: evidence_target requests evidence outside the capabilities of '${step.tool}'`
          );
        }
      }
    );
  }

} else if (plan !== null) {

  errors.push(
    "investigation plan must be a JSON object"
  );
}


// --------------------------------------------------
// 10. Final validation result
// --------------------------------------------------

const valid =
  errors.length === 0;


// --------------------------------------------------
// 11. Controlled output
// --------------------------------------------------

return [
  {
    json: {
      valid,

      errors,

      plan,

      validation_metadata: {
        validator:
          "investigation_plan_validator",

        validator_version:
          "1.0",

        validated_at:
          new Date().toISOString(),

        error_count:
          errors.length
      }
    }
  }
];
